import{_ as e,o as i,c as t,ag as s}from"./chunks/framework.CxkNbRKf.js";const g=JSON.parse('{"title":"Upgrade from 5.5 to 5.6","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/upgrade/upgrade-56.md","filePath":"installation-guide/upgrade/upgrade-56.md","lastUpdated":1786379412000}'),n={name:"installation-guide/upgrade/upgrade-56.md"};function o(r,a,l,d,p,c){return i(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="upgrade-from-5-5-to-5-6" tabindex="-1">Upgrade from 5.5 to 5.6 <a class="header-anchor" href="#upgrade-from-5-5-to-5-6" aria-label="Permalink to &quot;Upgrade from 5.5 to 5.6&quot;">​</a></h1><p>This upgrade covers database and configuration changes from NADA <strong>5.5.x</strong> to <strong>5.6</strong>.</p><p>Deploy the NADA <strong>5.6</strong> application files (zip release or Git tag) over your existing install, preserve your <code>application/config</code> customizations, and clear caches if your environment uses them. Then apply the steps below <strong>in order</strong>.</p><h2 id="_1-backup-database" tabindex="-1">1. Backup database <a class="header-anchor" href="#_1-backup-database" aria-label="Permalink to &quot;1. Backup database&quot;">​</a></h2><p>Before you change the database, take a full backup.</p><h2 id="_2-update-configuration" tabindex="-1">2. Update configuration <a class="header-anchor" href="#_2-update-configuration" aria-label="Permalink to &quot;2. Update configuration&quot;">​</a></h2><h3 id="auth-local-php-new-required-file" tabindex="-1">auth.local.php (new required file) <a class="header-anchor" href="#auth-local-php-new-required-file" aria-label="Permalink to &quot;auth.local.php (new required file)&quot;">​</a></h3><p>In 5.6, email credentials and authentication secrets have moved from <code>email.php</code> and <code>config.php</code> into a new file: <code>application/config/auth.local.php</code>.</p><p>Copy the sample template and fill in your values:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/config/auth.local.php.sample</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/config/auth.local.php</span></span></code></pre></div><p>Move your SMTP credentials, SendGrid API key (if used), and any OAuth client secrets into this file. It is excluded from version control and must not be committed.</p><h2 id="_3-run-php-migrations" tabindex="-1">3. Run PHP migrations <a class="header-anchor" href="#_3-run-php-migrations" aria-label="Permalink to &quot;3. Run PHP migrations&quot;">​</a></h2><p>Run the built-in CLI migration runner <strong>before</strong> opening the admin interface:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli/migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> latest</span></span></code></pre></div><p>This applies all database schema changes for 5.6.</p><p>If the command fails or the database was partly upgraded already, see <a href="/nada-documentation/installation-guide/database-migrations-cli.html">Database migrations (CLI)</a>.</p><h2 id="what-s-new-in-5-6" tabindex="-1">What&#39;s new in 5.6 <a class="header-anchor" href="#what-s-new-in-5-6" aria-label="Permalink to &quot;What&#39;s new in 5.6&quot;">​</a></h2><ul><li><strong>Vue 3 admin interface</strong> — catalog, dashboard, facets, site configuration, and menu management pages rebuilt in Vue 3</li><li><strong>OAuth social login</strong> — configurable providers via <code>auth.local.php</code></li><li><strong>Revamped permissions</strong> — per-user and per-collection access control</li><li><strong>Vue 3 catalog search</strong> — replaces legacy PHP search pages</li><li><strong>Time-series &amp; indicator support</strong> — Data Structure Definitions, codelists, dimension facets, and embeddable indicator charts</li><li><strong>ZIP/JSON import</strong> — import packages directly from the Metadata Editor</li><li><strong>Resumable file uploads</strong> — bypasses PHP upload size limits for large data files</li><li><strong>Built-in analytics</strong> — page-view and download tracking with server-side deduplication, admin dashboard, and API logs interface</li><li><strong>SHA-256 API key hashing</strong> — with expiry and revocation support; legacy keys must be regenerated</li><li><strong>SendGrid API email driver</strong> — alternative to SMTP, configured in <code>auth.local.php</code></li><li><strong>ISO 3-letter country codes</strong> — added to country lookups</li><li><strong>PHP 8.x compatibility</strong> improvements</li><li><strong>Widgets</strong> — Bootstrap and jQuery dependencies removed (already introduced in 5.5.1)</li></ul>',18)])])}const u=e(n,[["render",o]]);export{g as __pageData,u as default};
